<?php
declare(strict_types=1);
require dirname(__DIR__).'/system/core/Bootstrap/autoload.php';
use Cms\Core\Config\Settings;use Cms\Core\Navigation\NavigationBuilder as N;use Cms\Core\Theme\{ThemeViewModel,TemplateContext,ThemeRuntime,ThemeManifest};use Cms\Core\Admin\AdminController;use Cms\Core\Logging\FileLogger;use Cms\Core\Http\Request;use Cms\Core\Security\CsrfToken;
$root=sys_get_temp_dir().'/cms-navigation-'.bin2hex(random_bytes(5));mkdir($root.'/config',0700,true);define('CMS_ROOT',$root);session_start();
$p=new PDO('sqlite:'.$root.'/test.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$m=array_map(static fn($f)=>require$f,glob(dirname(__DIR__).'/system/migrations/*.php'));(new Cms\Core\Migration\MigrationRunner($p,$m))->run();
$checks=0;$check=static function(bool$v,string$m)use(&$checks){if(!$v)throw new RuntimeException($m);$checks++;echo "PASS $m\n";};
$legacy=[['label'=>'首页','url'=>'/'],['label'=>'文档','url'=>'/docs'],['label'=>'外站','url'=>'https://example.com/']];
$settings=static fn($items)=>Settings::fromArray(['navigation'=>['primary'=>$items],'database'=>['dsn'=>'sqlite:'.$root.'/test.sqlite']]);
$check(array_column(N::build($settings($legacy),$p),'url')===array_column($legacy,'url'),'Legacy links, order and destinations remain intact');
$check(count(N::buildTree($settings($legacy),$p))===3,'Legacy flat menu becomes equivalent roots');
$check(N::build($settings([]),$p)===[]&&N::buildTree($settings([]),$p)===[],'Explicit empty navigation stays empty');
$rows=[['id'=>'home','label'=>'首页','url'=>'/','sort_order'=>0],['id'=>'products','label'=>'产品','type'=>'group','sort_order'=>1],['id'=>'demo','label'=>'演示','url'=>'https://demo.example.com/','parent_id'=>'products','sort_order'=>2],['id'=>'plugins','label'=>'插件','url'=>'/plugins','parent_id'=>'products','sort_order'=>3],['id'=>'download','label'=>'下载','url'=>'/download','sort_order'=>4,'presentation'=>'button']];
$clean=N::sanitizeForSave($rows);$tree=N::buildTree($settings($clean),$p);$check(count($tree)===3&&array_column($tree[1]['children'],'id')===['demo','plugins'],'Two-level tree preserves ordered children');
$check(count(N::build($settings($clean),$p))===4,'Old flat public API retains every usable child link');
$check($tree[2]['presentation']==='button','Button presentation is configured data');
$off=$clean;$off[1]['enabled']=false;$check(count(N::build($settings($off),$p))===2,'Hidden parent hides descendants');
$off=$clean;$off[2]['requires_plugin']='missing.plugin';$check(count(N::buildTree($settings($off),$p)[1]['children'])===1,'Unavailable plugin links are filtered');
$off[3]['enabled']=false;$check(count(N::buildTree($settings($off),$p))===2,'Empty unavailable group is omitted');
$check(count(N::adminItems($settings($off),$p))===5,'Disabled and unavailable items remain editable');
$sorted=$rows;$sorted[3]['sort_order']=2;$check(array_column(N::sanitizeForSave($sorted),'id')===['home','products','demo','plugins','download'],'Equal sort values preserve input order');
foreach(['duplicate','cycle','orphan','depth','child-group','bad-url','slash-url','control-url','oversize','scalar']as$case){$bad=$rows;switch($case){case'duplicate':$bad[2]['id']='home';break;case'cycle':$bad[0]['parent_id']='download';$bad[4]['parent_id']='home';break;case'orphan':$bad[2]['parent_id']='absent';break;case'depth':$bad[3]['parent_id']='demo';break;case'child-group':$bad[1]['parent_id']='home';break;case'bad-url':$bad[0]['url']='javascript:alert(1)';break;case'slash-url':$bad[0]['url']='/\\evil.example';break;case'control-url':$bad[0]['url']="/bad\nurl";break;case'oversize':$bad=array_fill(0,201,$rows[0]);break;case'scalar':$bad[]='bad';break;}$thrown=false;try{N::sanitizeForSave($bad);}catch(InvalidArgumentException){$thrown=true;}$check($thrown,'Invalid '.$case.' fails before persistence');}
$vm=ThemeViewModel::menuTree($tree,'/plugins');$check($vm[1]['active']&&$vm[1]['children'][1]['current'],'Active child marks its parent active');
$nested=ThemeViewModel::menuTree([['title'=>'分类','type'=>'group','children'=>[['title'=>'子项','href'=>'/child']]]]);$check(count($nested)===1&&$nested[0]['children'][0]['url']==='/child','Theme nested menu without IDs supports legacy label aliases');
$check(ThemeViewModel::menuTree([['label'=>'坏链接','url'=>'javascript:x']])===[],'Malformed optional theme menu cannot break page');
$runtime=new ThemeRuntime(ThemeManifest::fromArray(['theme_id'=>'fixture','name'=>'Fixture','author'=>'Fixture','version'=>'1.0.0','core'=>['min'=>'1.2.0']]),$root,[]);
$context=new TemplateContext($runtime,['navigation'=>N::build($settings($clean),$p),'navigation_tree'=>$tree]);$check(count($context->menu())===4&&count($context->menuTree())===3,'Theme exposes additive tree while legacy menu stays flat');
$context=new TemplateContext($runtime,['navigation_tree'=>$tree,'menus'=>['primary'=>[]]]);$check($context->menuTree()===[],'Explicit theme menu override takes precedence');
Cms\Core\Routing\BasePath::setCurrent('/cms');
$_SERVER['REQUEST_URI']='/cms/plugins?q=1';
$context=new TemplateContext($runtime,['navigation_tree'=>$tree]);$prefixed=$context->menuTree();
$check($prefixed[1]['active']&&$prefixed[1]['children'][1]['url']==='/cms/plugins','Request path and subdirectory activate configured child');
$check($prefixed[1]['children'][0]['url']==='https://demo.example.com/','Subdirectory leaves external destinations unchanged');
Cms\Core\Routing\BasePath::setCurrent('');unset($_SERVER['REQUEST_URI']);
// Actual controller persistence, authentication, CSRF and retained config.
$config=['app'=>['version'=>'1.2.87'],'site'=>['name'=>'Fixture'],'database'=>['dsn'=>'sqlite:'.$root.'/test.sqlite'],'navigation'=>['primary'=>$legacy],'keep'=>['sentinel'=>42]];
file_put_contents($root.'/config/app.php','<?php return '.var_export($config,true).';');
$make=static fn()=>new AdminController(Settings::load($root),new FileLogger($root.'/test.log'),$root);
$check($make()->navigationIndex()->status()===302,'Guest cannot open navigation administration');
$auth=new Cms\Core\Auth\AdminAuthenticator($p);$auth->createAdmin('nav@example.invalid','Navigation-test-2026!','Fixture');$check($auth->attempt('nav@example.invalid','Navigation-test-2026!','127.0.0.1'),'Actual isolated administrator signs in');
$post=static fn(array$b)=>new Request('POST','/admin/navigation',[],$b);
$check($make()->navigationSave($post(['navigation'=>$clean]))->status()===403,'Navigation mutation requires CSRF');
$token=CsrfToken::get();$check($make()->navigationSave($post(['_csrf'=>$token,'navigation'=>$clean,'navigation_count'=>'5','navigation_complete'=>'1']))->status()===302,'Actual admin route saves hierarchy');
$saved=Settings::load($root);$check($saved->get('navigation.primary')===$clean&&$saved->get('keep.sentinel')===42,'Persistence retains unrelated configuration and hierarchy');
$bytes=file_get_contents($root.'/config/app.php');$check($make()->navigationSave($post(['_csrf'=>$token,'navigation'=>$clean,'navigation_count'=>'5']))->status()===400&&file_get_contents($root.'/config/app.php')===$bytes,'Truncated browser form cannot erase saved menu');
$bad=$clean;$bad[2]['parent_id']='demo';$check($make()->navigationSave($post(['_csrf'=>$token,'navigation'=>$bad]))->status()===400&&file_get_contents($root.'/config/app.php')===$bytes,'Invalid hierarchy does not partially overwrite config');
$r=$make()->navigationSave($post(['_csrf'=>$token,'navigation'=>$clean,'nav_delete'=>'products']));$after=Settings::load($root)->get('navigation.primary');$check($r->status()===302&&count($after)===4&&array_column($after,'parent_id')===['','','',''],'Deleting group promotes children without losing links');
$check($make()->navigationSave($post(['_csrf'=>$token,'navigation'=>$after,'quick_add'=>'group','new_label'=>'资源']))->status()===302,'Admin can add a named non-link group');
$hidden=$after;$hidden[0]['enabled']='0';$check($make()->navigationSave($post(['_csrf'=>$token,'navigation'=>$hidden]))->status()===302&&!Settings::load($root)->get('navigation.primary')[0]['enabled'],'Unchecked visibility persists as disabled');
$html=$make()->navigationIndex()->body();$check(str_contains($html,'[parent_id]')&&str_contains($html,'[sort_order]')&&str_contains($html,'[presentation]')&&str_contains($html,'navigation_complete'),'Admin renders generic hierarchy, ordering, presentation and form guard');
$check($p->query('PRAGMA integrity_check')->fetchColumn()==='ok','Native fixture database remains intact');
echo "Checks: $checks; network requests: 0; production writes: 0\n";
